        let relative = file
            .strip_prefix(&src_dir)
            .unwrap_or(&file)
            .to_string_lossy()
            .replace('\\', "/");
        if !MAP_ERR_IGNORE_ALLOWLIST.contains(&relative.as_str()) {
            violations.push(relative);
        }
    }

