                .map(ReleaseMissingWork::from)
                .collect(),
        },
        OperationObservation::Exact(evidence) => ReleaseReadinessState::Exact(evidence),
        OperationObservation::Conflict(conflict) => ReleaseReadinessState::Conflict(conflict.into()),
        OperationObservation::Unverifiable(failure) => ReleaseReadinessState::Unverifiable(failure.into()),
    }
}

