fn readiness_state(observation: OperationObservation) -> ReleaseReadinessState {
    match observation {
        OperationObservation::Absent => ReleaseReadinessState::Absent,
        OperationObservation::Incomplete(partial) => ReleaseReadinessState::Incomplete {
            exact: partial.exact().to_vec(),
            missing: partial
                .missing()
                .iter()
                .cloned()
                .map(ReleaseMissingWork::from)
                .collect(),
        },
        OperationObservation::Exact(evidence) => ReleaseReadinessState::Exact(evidence),
        OperationObservation::Conflict(conflict) => ReleaseReadinessState::Conflict(conflict.into()),
        OperationObservation::Unverifiable(failure) => ReleaseReadinessState::Unverifiable(failure.into()),
    }
}

